// EmployeeDashboard.jsx - Fixed & Enhanced Version (Corrected API Call, Added Await, Improved UI & Error Handling)
// Aligned with Sanchar Helpdesk PDF: Purple theme, modern cards, status counts matching "Newly Created", "In Progress", "Closed", "Partially Closed"
import React, { useEffect, useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { Link } from 'react-router-dom';
import api from "../api/axios"; // Custom axios with interceptors (handles token automatically)
import { useNavigate } from 'react-router-dom';

const EmployeeDashboard = () => {
  const dispatch = useDispatch();
  const token = useSelector((state) => state.auth.token);
  const user = useSelector((state) => state.auth.user);
  const navigate = useNavigate();

  const [tickets, setTickets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!user || !token) {
      setError('Please log in to view your tickets.');
      setLoading(false);
      return;
    }

    const fetchTickets = async () => {
      try {
        // Use await for async call (fix: missing await caused undefined response)
        const response = await api.get("/tickets/"); // Token handled by axios interceptor

        // Filter tickets created by current user
        const myTickets = response.data.filter(
          (ticket) => ticket.creator?.id?.toString() === user.id?.toString()
        );

        setTickets(myTickets);
      } catch (err) {
        console.error('Fetch error:', err);
        const message = err.response?.status === 401
          ? 'Session expired. Please log in again.'
          : 'Failed to load tickets. Please try again.';
        setError(message);

        // Auto-logout on 401
        if (err.response?.status === 401) {
          dispatch({ type: 'auth/logout' });
        }
      } finally {
        setLoading(false);
      }
    };

    fetchTickets();
  }, [token, user, dispatch]);

  // Status counts inspired by PDF: NEW (mapped to OPEN), IN_PROGRESS, CLOSED (RESOLVED), PARTIALLY_CLOSED
  const statusCounts = {
    NEW: tickets.filter(t => t.status === 'OPEN').length,
    IN_PROGRESS: tickets.filter(t => t.status === 'IN_PROGRESS').length,
    CLOSED: tickets.filter(t => t.status === 'RESOLVED').length,
    PARTIALLY_CLOSED: tickets.filter(t => t.status === 'PARTIALLY_CLOSED').length || 0,
  };

  const getPriorityColor = (priority) => {
    const p = priority?.toUpperCase() || '';
    if (p.includes('VERY HIGH') || p.includes('HIGH')) return 'linear-gradient(135deg, #ff4d4f, #cf1322)';
    if (p === 'MEDIUM' || p === 'NORMAL') return 'linear-gradient(135deg, #faad14, #d48806)';
    if (p === 'LOW') return 'linear-gradient(135deg, #52c41a, #389e0d)';
    return 'linear-gradient(135deg, #d9d9d9, #bfbfbf)';
  };

  const getStatusColor = (status) => {
    const s = status?.toUpperCase() || '';
    switch (s) {
      case 'OPEN': return 'linear-gradient(135deg, #1890ff, #096dd9)';
      case 'IN_PROGRESS': return 'linear-gradient(135deg, #faad14, #d48806)';
      case 'RESOLVED': return 'linear-gradient(135deg, #52c41a, #389e0d)';
      case 'PARTIALLY_CLOSED': return 'linear-gradient(135deg, #9254de, #722ed1)';
      default: return 'linear-gradient(135deg, #d9d9d9, #bfbfbf)';
    }
  };

  if (loading) return <div style={styles.loading}>Loading your tickets...</div>;
  if (error) return <div style={styles.error}>{error}</div>;

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h2 style={styles.title}>Sanchar Helpdesk - My Tickets</h2>
        <Link to="/tickets/create" style={styles.createButton}>Create New Ticket</Link>
      </div>

      {/* Status Count Cards - PDF Style */}
      <div style={styles.countsGrid}>
        <div style={{ ...styles.countCard, background: getStatusColor('OPEN') }}>
          <span style={styles.countIcon}>🆕</span>
          <h3 style={styles.countNumber}>{statusCounts.NEW}</h3>
          <p style={styles.countLabel}>New Tickets</p>
        </div>
        <div style={{ ...styles.countCard, background: getStatusColor('IN_PROGRESS') }}>
          <span style={styles.countIcon}>⚙️</span>
          <h3 style={styles.countNumber}>{statusCounts.IN_PROGRESS}</h3>
          <p style={styles.countLabel}>In Progress</p>
        </div>
        <div style={{ ...styles.countCard, background: getStatusColor('RESOLVED') }}>
          <span style={styles.countIcon}>✅</span>
          <h3 style={styles.countNumber}>{statusCounts.CLOSED}</h3>
          <p style={styles.countLabel}>Closed</p>
        </div>
        <div style={{ ...styles.countCard, background: getStatusColor('PARTIALLY_CLOSED') }}>
          <span style={styles.countIcon}>🔒</span>
          <h3 style={styles.countNumber}>{statusCounts.PARTIALLY_CLOSED}</h3>
          <p style={styles.countLabel}>Partially Closed</p>
        </div>
      </div>

      {/* Ticket List */}
      {tickets.length === 0 ? (
        <div style={styles.noTickets}>
          <p>You haven't created any tickets yet.</p>
        </div>
      ) : (
        <div style={styles.ticketsGrid}>
          {tickets.map((ticket) => (
            <Link to={`/tickets/${ticket.id}`} key={ticket.id} style={styles.ticketLink}>
              <div style={styles.ticketCard}>
                <div style={styles.ticketHeader}>
                  <h4 style={styles.ticketTitle}>#{ticket.id} - {ticket.title}</h4>
                  <span style={{ ...styles.badge, background: getPriorityColor(ticket.priority) }}>
                    {ticket.priority}
                  </span>
                  <span style={{ ...styles.badge, background: getStatusColor(ticket.status) }}>
                    {ticket.status}
                  </span>
                </div>
                <p style={styles.ticketDescription}>{ticket.description?.substring(0, 150)}...</p>
                <p style={styles.ticketMeta}>
                  Created: {new Date(ticket.created_at).toLocaleDateString()}
                </p>
              </div>
            </Link>
          ))}
        </div>
      )}
    </div>
  );
};

// Attractive Styles - Purple Theme from Sanchar Helpdesk PDF
const styles = {
  container: {
    padding: '40px 20px',
    maxWidth: '1400px',
    margin: '0 auto',
    background: 'linear-gradient(to bottom, #f9faff, #ffffff)',
    minHeight: '100vh',
    fontFamily: 'Arial, sans-serif',
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '40px',
  },
  title: {
    fontSize: '32px',
    margin: 0,
    color: '#4527a0', // Purple from PDF
    fontWeight: '700',
  },
  createButton: {
    padding: '12px 24px',
    background: 'linear-gradient(135deg, #7c4dff, #4527a0)',
    color: '#ffffff',
    borderRadius: '8px',
    textDecoration: 'none',
    fontWeight: '600',
    fontSize: '16px',
  },
  countsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))',
    gap: '24px',
    marginBottom: '48px',
  },
  countCard: {
    padding: '32px 24px',
    borderRadius: '16px',
    textAlign: 'center',
    boxShadow: '0 8px 24px rgba(0,0,0,0.1)',
    color: '#ffffff',
    transition: 'transform 0.3s ease',
  },
  countIcon: {
    fontSize: '40px',
    marginBottom: '16px',
    display: 'block',
  },
  countNumber: {
    fontSize: '48px',
    margin: '0 0 12px',
    fontWeight: '800',
  },
  countLabel: {
    fontSize: '20px',
    margin: 0,
    fontWeight: '600',
  },
